import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {useMemo} from 'react'
import type * as React from 'react'

import {useSaveChangesState} from '../../../components/ChangesButton/hooks/useSaveChangesState'
import {usePipelineId} from '../../../hooks/pipeline'
import {makeTotalCountPipelineErrorsSelector} from '../../EditPipelinePage.selectors'
import SidebarFooterContainer from '../SidebarFooterContainer/SidebarFooterContainer'

import styles from './SidebarFooter.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  children?: React.ReactNode
}

function SidebarFooter({children}: Props) {
  const pipelineId = usePipelineId()
  const {hasChanges} = useSaveChangesState()

  const selector = useMemo(() => makeTotalCountPipelineErrorsSelector(), [])
  const errorCount = useAppSelector(state => selector(state, {pipelineId}))

  return (
    <SidebarFooterContainer>
      <div className={styles.status}>
        {hasChanges && <span>{'You have unsaved changes'}</span>}
        {errorCount > 0 && (
          <span className={styles.errors}>
            <SvgIcon className={styles.errorIcon} icon={'muted'} title={'Error'} />
            {errorCount}
          </span>
        )}
      </div>
      {children}
    </SidebarFooterContainer>
  )
}

export default SidebarFooter
