import classnames from 'classnames'
import type React from 'react'
import {Fragment, useMemo} from 'react'
import {useNavigate} from 'react-router'

import {getPipelineHref} from '../../../../../routes'
import {restApi} from '../../../../../services/rest'
import {usePipelineId} from '../../hooks/pipeline'

type ReusedJobStatusLinkProps = {
  jobId?: string
  prefix?: string | null
  suffix?: string | null
  placeholder?: string | null
  link?: boolean
}

function ReusedJobStatusLink({jobId, prefix, suffix, placeholder, link}: ReusedJobStatusLinkProps) {
  const navigate = useNavigate()
  const pipelineId = usePipelineId()
  const {triggeredRunId, triggeredRunNumber} = restApi.endpoints.getBuildNormalized.useQuery(
    {
      buildLocator: `${jobId}`,
      fields: 'id,triggered(build(id,buildTypeId(id,project(internalId)),number))',
    },
    {
      selectFromResult: ({data}) => {
        const triggeredRun = data?.entities?.builds?.[data?.result!]?.triggered?.build

        return {
          triggeredRunId: triggeredRun?.id,
          triggeredRunNumber: triggeredRun?.number,
        }
      },
      skip: !jobId,
    },
  )
  const toTriggeredRun = useMemo(
    () => ({
      pathname: getPipelineHref(pipelineId, String(triggeredRunId)),
      search: `job=${jobId}`,
    }),
    [jobId, pipelineId, triggeredRunId],
  )
  const clickTriggeredRunLinkHandler = (event: React.MouseEvent<HTMLElement>) => {
    event.stopPropagation()
    event.preventDefault()
    if (link) {
      navigate(toTriggeredRun)
    }
  }
  const linkClassNames = classnames({'ring-link-link': link})

  if (triggeredRunId) {
    return (
      <Fragment>
        {prefix}
        <span
          role="presentation"
          onClick={clickTriggeredRunLinkHandler}
          className={linkClassNames}
        >{`Run #${triggeredRunNumber}`}</span>
        {suffix}
      </Fragment>
    )
  }

  return placeholder
}

export default ReusedJobStatusLink
