/**
 * Extracts a file path from either a string or an object with a path property.
 * @param file - The file which can be a string or an object with a path property
 * @returns The file path or null if the file is invalid
 */
const extractFilePath = (file: any): string | null => {
  if (typeof file === 'string') {
    return file
  } else if (typeof file === 'object') {
    return file?.path
  }
  return null
}

/**
 * Maps an array of files to their paths and filters out null values.
 * @param files - Array of files which can be strings or objects with path properties
 * @returns Array of file paths with null values filtered out
 */
export const extractFilePaths = (files: any[]): string[] =>
  files.map(extractFilePath).filter((file): file is string => file != null)
