import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import classNames from 'classnames'

import Pager from '../../../../../common/PagerNew/PagerNew'
import type {pipelineHeadBuildTypeFragment$key} from '../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'

import {usePipelineHistory} from './PipelineHistory.hooks'
import PipelineRunLine from './PipelineRunLine/PipelineRunLine'

import styles from './PipelineHistory.module.css'

function Empty() {
  return (
    <>
      <H2 className={styles.emptyListHeading}>{'There are no runs yet'}</H2>
      <p className={styles.emptyListDescription}>
        {`Try setting up the pipeline by going into Edit mode.
          You can also start it by clicking the Run button.`}
      </p>
    </>
  )
}

type Props = {
  className?: string
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
}

function PipelineHistory({className, pipelineHeadBuildTypeKey}: Props) {
  const {ids, pager} = usePipelineHistory(pipelineHeadBuildTypeKey)

  const renderContent = () => {
    if (ids.length === 0) {
      return <Empty />
    }
    return (
      <div className={styles.wrapper}>
        <div className={styles.runs}>
          <div className={styles.columnHeader}>{'Run number'}</div>
          <div className={styles.columnHeader}>{'Status'}</div>
          <div className={styles.columnHeader}>{'Branch'}</div>
          <div className={styles.columnHeader}>{'Changes'}</div>
          <div className={classNames(styles.columnHeader, styles.startDate)}>{'Start time'}</div>
          <div className={styles.columnHeader}>{'Duration'}</div>
          <div className={styles.columnUnderline} />
          {ids.map(runId => (
            <div key={runId} className={styles.line}>
              <PipelineRunLine runId={runId} pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey} />
              <div className={styles.columnUnderline} />
            </div>
          ))}
        </div>
        <Pager {...pager} className={styles.pager} />
      </div>
    )
  }

  return (
    <div className={classNames(className, styles.container, {[styles.empty]: ids.length === 0})}>
      {renderContent()}
    </div>
  )
}

export default PipelineHistory
