import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import {formatDistance, parseISO} from 'date-fns'
import {useEffect} from 'react'

import {subscribeOnBuild} from '../../../../../../../actions/builds'
import {getPipelineHref} from '../../../../../../../routes'
import {restApi} from '../../../../../../../services/rest'
import type {BuildId} from '../../../../../../../types'
import {stringifyBranch} from '../../../../../../../utils/branchNames'
import {useDisplayDate} from '../../../../../../../utils/dateTimeUtils'
import BranchLabel from '../../../../../../common/BranchLabel/BranchLabel'
import {formatBuildNumber} from '../../../../../../common/BuildNumber/BuildNumber.utils'
import RouterLink from '../../../../../../common/RouterLink/RouterLink'
import StopBuild from '../../../../../../common/StopBuild/StopBuild.container'
import BuildChangesDropdown from '../../../../../../packages/Changes/BuildChangesDropdown/BuildChangesDropdown'
import RunStatus from '../../../../components/RunStatus/RunStatus'
import type {pipelineHeadBuildTypeFragment$key} from '../../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineId} from '../../../../hooks/pipeline'
import {usePipelineHistoryArg} from '../PipelineHistory.hooks'

import RunTimeBar from './RunTimeBar/RunTimeBar'

import styles from './PipelineRunLine.module.css'

import {useAppDispatch} from 'src/hooks/react-redux'

type Props = {
  runId: BuildId
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
}

export default function PipelineRunLine({runId, pipelineHeadBuildTypeKey}: Props) {
  const id = usePipelineId()
  const arg = usePipelineHistoryArg(pipelineHeadBuildTypeKey)
  const {run} = restApi.endpoints.getAllBuildsNormalized.useQuery(arg, {
    selectFromResult: ({data}) => ({run: data?.entities.builds?.[runId]}),
  })
  const {number, state, startEstimate, startDate, finishDate, branchName, defaultBranch} = run ?? {}
  const isQueued = state === 'queued'
  const isRunning = state === 'running'
  const href = getPipelineHref(id, String(runId))
  const startDateFormatted = useDisplayDate(startDate, true)
  const startEstimateFormatted = useDisplayDate(startEstimate, true)
  const dispatch = useAppDispatch()
  useEffect(() => dispatch(subscribeOnBuild(runId)))

  return (
    <>
      <div className={styles.cell}>
        {!isQueued && (
          <RouterLink to={href} className={styles.number}>
            {formatBuildNumber({number}).text}
          </RouterLink>
        )}
      </div>
      <div className={styles.cell}>
        <RunStatus {...run} className={styles.status} />
      </div>
      <div className={styles.cell}>
        {branchName != null && (
          <BranchLabel
            name={branchName}
            main={defaultBranch}
            to={{
              search: objectToQuery({
                branch: stringifyBranch({default: defaultBranch, name: branchName}),
              }),
            }}
          />
        )}
      </div>
      <div className={styles.cell}>
        <BuildChangesDropdown buildId={runId} />
      </div>
      <div className={classNames(styles.cell, styles.startDate)}>
        {isQueued ? (
          startEstimate != null ? (
            <span className={styles.estimate}>{`~${startEstimateFormatted}`}</span>
          ) : null
        ) : (
          startDateFormatted
        )}
      </div>
      <div className={classNames(styles.cell, styles.duration)}>
        {isQueued || isRunning ? (
          <RunTimeBar runId={runId} />
        ) : startDate != null && finishDate != null ? (
          formatDistance(parseISO(startDate), parseISO(finishDate))
        ) : null}
      </div>
      <div className={styles.cell}>
        {isQueued || isRunning ? <StopBuild buildId={runId} withBorder /> : null}
      </div>
    </>
  )
}
