import classNames from 'classnames'
import {useEffect, useMemo} from 'react'
import {graphql} from 'react-relay'

import {useRefetchableLazyLoadQuery} from '../../../../../../hooks/relay/useRefetchableLazyLoadQuery'
import {emptyArray} from '../../../../../../utils/empty'
import {subscribeOnProjectEvents} from '../../../../../../utils/subscriber'
import {
  BUILD_FINISHED,
  BUILD_INTERRUPTED,
  BUILD_STARTED,
  BUILD_TYPE_ADDED_TO_QUEUE,
  BUILD_TYPE_REMOVED_FROM_QUEUE,
} from '../../../../../../utils/subscriptionEvents'
import PipelineChart from '../../../components/PipelineChart/PipelineChart'
import EditPipelineJob from '../../../EditPipelinePage/EditPipelineChart/EditPipelineJob/EditPipelineJob'
import {usePipelineGraph} from '../../../EditPipelinePage/EditPipelinePage.hooks'
import {getStringifiedDependencies} from '../../../EditPipelinePage/EditPipelinePage.selectors'
import type {pipelineHeadBuildTypeFragment$key} from '../../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineId} from '../../../hooks/pipeline'
import {pipelinesApi} from '../../../services/pipelinesApi'
import {createGraph} from '../../../utils/graph'

import type {PipelineLastRunQuery} from './__generated__/PipelineLastRunQuery.graphql'
import {useLastRunLocator} from './PipelineLastRun.hooks'
import PipelineLastRunJob from './PipelineLastRunJob/PipelineLastRunJob'

import styles from './PipelineLastRun.module.css'

const NODE_HEIGHT = 88
const NODE_WIDTH = 192
const GAP_HORIZONTAL = 32
const GAP_VERTICAL = 16

type Props = {
  className?: string
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
}

const query = graphql`
  query PipelineLastRunQuery($locator: String!) {
    builds(locator: $locator) {
      build {
        id
        snapshotDependencies {
          build {
            id
            buildType {
              project {
                internalId
              }
            }
            snapshotDependencies {
              build {
                id
              }
            }
            ...PipelineLastRunJobFragment
          }
        }
      }
    }
  }
`

export default function PipelineLastRun({className, pipelineHeadBuildTypeKey}: Props) {
  const locator = useLastRunLocator(pipelineHeadBuildTypeKey)
  const [{builds}, refetch] = useRefetchableLazyLoadQuery<PipelineLastRunQuery>(query, {
    locator,
  })
  const {id: lastRunId, snapshotDependencies} = builds?.build?.[0] ?? {}
  const dependencies = snapshotDependencies?.build
  const isEmpty = builds != null && !builds?.build?.length
  const pipelineId = usePipelineId()
  const childInternalId = dependencies?.[0]?.buildType?.project?.internalId
  useEffect(
    () =>
      childInternalId != null
        ? subscribeOnProjectEvents(
            childInternalId,
            [
              BUILD_TYPE_ADDED_TO_QUEUE,
              BUILD_TYPE_REMOVED_FROM_QUEUE,
              BUILD_STARTED,
              BUILD_FINISHED,
              BUILD_INTERRUPTED,
            ],
            refetch,
          )
        : undefined,
    [childInternalId, refetch],
  )
  const {stringifiedDependencies} = pipelinesApi.endpoints.getPipelineById.useQuery(pipelineId, {
    selectFromResult: ({data}) => ({
      stringifiedDependencies: getStringifiedDependencies(data?.settings.jobs),
    }),
  })
  const configuredGraph = usePipelineGraph(stringifiedDependencies)
  const graph = useMemo(
    () =>
      dependencies &&
      createGraph({
        data: dependencies,
        getId: build => String(build.id),
        getDependencies: build =>
          build.snapshotDependencies?.build?.map(dep => String(dep.id)) ?? emptyArray,
      }),
    [dependencies],
  )

  const isReady = isEmpty ? configuredGraph != null : lastRunId != null

  return isReady ? (
    <div className={classNames(className, styles.lastRunWrapper)}>
      <div className={styles.lastRun}>
        {isEmpty
          ? configuredGraph != null && (
              <PipelineChart
                className={styles.lastRunChart}
                graph={configuredGraph}
                nodeWidth={NODE_WIDTH}
                nodeHeight={NODE_HEIGHT}
                gapHorizontal={GAP_HORIZONTAL}
                gapVertical={GAP_VERTICAL}
                renderJob={({data, x, y}) => (
                  <EditPipelineJob
                    x={y! - NODE_WIDTH / 2 - GAP_HORIZONTAL / 2}
                    y={x! - NODE_HEIGHT / 2 - GAP_VERTICAL / 2}
                    selected={false}
                    isNew={false}
                    key={data.id}
                    id={data.id}
                    pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey}
                    withLabel={false}
                    readOnly
                  />
                )}
              />
            )
          : graph != null && (
              <PipelineChart
                className={styles.lastRunChart}
                graph={graph}
                nodeWidth={NODE_WIDTH}
                nodeHeight={NODE_HEIGHT}
                gapHorizontal={GAP_HORIZONTAL}
                gapVertical={GAP_VERTICAL}
                renderJob={({data, x, y}) => (
                  <PipelineLastRunJob
                    x={x! - NODE_HEIGHT / 2 - GAP_VERTICAL / 2}
                    y={y! - NODE_WIDTH / 2 - GAP_HORIZONTAL / 2}
                    jobKey={data.data}
                    runId={String(lastRunId)}
                    key={data.id}
                  />
                )}
              />
            )}
      </div>
    </div>
  ) : null
}
