import {graphql, useFragment} from 'react-relay'

import {useRunningBuildUpdaterRelay} from '../../../../../../../hooks/relay/useRunningBuildUpdaterRelay'
import {useBuildStatusIconRelay} from '../../../../../../../hooks/useBuildStatusIcon'
import {getPipelineHref} from '../../../../../../../routes'
import RunJob from '../../../../components/RunJob/RunJob'
import {usePipelineId} from '../../../../hooks/pipeline'
import {usePipelineRunJobAgentCompatibilityStatus} from '../../../../PipelineRunPage/PipelineRunPage.hooks'

import type {PipelineLastRunJobFragment$key} from './__generated__/PipelineLastRunJobFragment.graphql'

type Props = {
  x: number
  y: number
  jobKey: PipelineLastRunJobFragment$key | null
  runId: string
}

const fragment = graphql`
  fragment PipelineLastRunJobFragment on Build {
    id
    buildType {
      id
      name
    }
    parallelized
    status
    state
    statusText
    waitReason
    attributes(locator: "name:teamcity.pipeline.job.id") {
      entry {
        name
        value
      }
    }
    artifacts {
      count
    }
    snapshotDependencies {
      build {
        runningInfo {
          percentageComplete
          leftSeconds
        }
      }
    }
    runningInfo {
      percentageComplete
      leftSeconds
    }
    ...useBuildStatusIconFragment
    ...useRunningBuildUpdaterRelayFragment
  }
`

export default function PipelineLastRunJob({x, y, jobKey, runId}: Props) {
  const id = usePipelineId()
  const job = useFragment(fragment, jobKey)
  const {id: jobId, runningInfo} = job ?? {}
  const icon = useBuildStatusIconRelay(job)
  const {isCurrentJobIncompatibilityAgent} = usePipelineRunJobAgentCompatibilityStatus(job)
  const runJobBuildType = {
    ...job?.buildType,
    id: job?.buildType?.id ?? undefined,
    name: job?.buildType?.name ?? '',
  }

  useRunningBuildUpdaterRelay(job)

  return (
    <RunJob
      {...job}
      jobId={jobId}
      runningInfo={{...runningInfo, elapsedSeconds: 0}}
      buildType={runJobBuildType}
      icon={icon}
      isIncompatibilityAgent={isCurrentJobIncompatibilityAgent}
      to={{
        pathname: getPipelineHref(id, runId),
        search: `job=${jobId}`,
      }}
      position={{x, y}}
    />
  )
}
